export const BODY: string = "\n<p>عند 100 كيلوبايت، الصيغة التي تختارها تقرر كيف تبدو الصورة. الصورة نفسها قد تبدو ممتازة بصيغة وضعيفة بأخرى، رغم تساوي الحجم.</p>\n<p>تخزّن JPG وPNG وWebP الصور بطرق مختلفة. نقاط قوتها تظهر بوضوح عند هذا الحجم، حيث يصبح كل كيلوبايت مهمًا.</p>\n<p>يقارن هذا المقال الصيغ الثلاث عند 100 كيلوبايت، لتختار الصحيحة للصور والرسوم والنصوص.</p>\n<h2 id=\"how-each-format-works\">كيف تحفظ كل صيغة الصورة؟</h2>\n<p>JPG يضغط الصور بحذف تفاصيل لا تلاحظها العين. هذه الطريقة فعالة جدًا للصور الفوتوغرافية، حيث التدرجات ناعمة والتفاصيل متداخلة.</p>\n<p>PNG يحفظ كل بكسل بدقة دون فقدان، لذلك يحتاج مساحة أكبر للصورة نفسها. أما WebP فيجمع بين تقنيات حديثة تجعله أصغر من JPG بجودة مماثلة.</p>\n<h2 id=\"jpg-at-100kb\">JPG عند 100 كيلوبايت</h2>\n<p>JPG عند 100 كيلوبايت ممتاز للصور الفوتوغرافية. الوجوه ناعمة والتدرجات سلسة، والملف يعمل في كل مكان دون مشاكل توافق.</p>\n<p>الضعف الوحيد أن النص داخل الصورة قد يفقد بعض حدته. لذلك تجنب JPG للصور التي تحمل نصًا صغيرًا مهمًا.</p>\n<h2 id=\"webp-at-100kb\">WebP عند 100 كيلوبايت</h2>\n<p>WebP عند 100 كيلوبايت يتفوق على JPG غالبًا. يبقي الحواف أنظف قليلًا بالحجم نفسه، ويحفظ التدرجات بسلاسة أكبر.</p>\n<p>المشكلة الوحيدة هي التوافق. معظم المتصفحات الحديثة تدعمه، لكن بعض البوابات القديمة وأنظمة الطباعة ترفضه ما زالت.</p>\n<h2 id=\"png-at-100kb\">PNG عند 100 كيلوبايت</h2>\n<p>PNG عند 100 كيلوبايت ضعيف للصور الفوتوغرافية. لأنه لا يحذف بيانات، يضطر إلى تقليص الأبعاد كثيرًا للوصول إلى الحد، فتبدو الصورة أصغر وأقل تفصيلًا.</p>\n<p>لكنه يتفوق في النصوص والرسوم المسطحة. الحروف تبقى حادة والخطوط نظيفة، وهذا ما يجعله الخيار الصحيح للرسوم لا للصور.</p>\n<h2 id=\"photos-compared\">الصور الفوتوغرافية مقارنة عند 100 كيلوبايت</h2>\n<p>للصور الفوتوغرافية، الترتيب واضح: WebP أولًا، ثم JPG بفارق صغير، ثم PNG بعيدًا في الخلف. الفرق بين WebP وJPG صغير لكنه حقيقي عند التكبير.</p>\n<p>إذا كانت بوابتك تقبل WebP، فاستخدمه. وإلا فـJPG يعطي نتيجة ممتازة، ولا حاجة إلى القلق بشأن الفرق البسيط.</p>\n<h2 id=\"graphics-compared\">الرسوم والنصوص مقارنة عند 100 كيلوبايت</h2>\n<p>للرسوم والنصوص، ينقلب الترتيب: PNG أولًا بفضل حدة الحروف، ثم WebP، ثم JPG. النص الصغير بصيغة JPG يبدو ضبابيًا عند 100 كيلوبايت.</p>\n<p>إذا كانت صورتك رسمًا بيانيًا أو شعارًا، فاختر PNG رغم حجمه الأكبر. وضوح النص يستحق الكيلوبايتات الإضافية.</p>\n<h2 id=\"screenshots-compared\">لقطات الشاشة مقارنة عند 100 كيلوبايت</h2>\n<p>لقطات الشاشة تجمع بين النص والصور، لذلك هي أصعب الحالات. PNG يحافظ على النص حادًا لكنه قد يتجاوز 100 كيلوبايت بسهولة.</p>\n<p>الحل الوسط أن تقص اللقطة على المنطقة المهمة فقط، ثم تضغط بصيغة JPG بجودة عالية. النص يبقى مقروءًا والحجم يناسب الحد.</p>\n<h2 id=\"transparency-compared\">الشفافية عند 100 كيلوبايت</h2>\n<p>الشفافية عند 100 كيلوبايت متاحة في PNG وWebP فقط. JPG لا يدعم الشفافية أبدًا، فسيملأ المناطق الشفافة بلون خلفية.</p>\n<p>إذا احتجت شفافية، فاختر WebP لأنه أصغر من PNG بكثير. أما إذا كان الشعار بسيطًا، فقد يناسب PNG رغم حجمه الأكبر.</p>\n<h2 id=\"which-format-when\">أي صيغة ومتى؟</h2>\n<p>القاعدة بسيطة: صور فوتوغرافية فاختر JPG أو WebP، ونصوص ورسوم فاختر PNG، وشفافية فاختر WebP أولًا.</p>\n<p>وعند الشك، جرّب الصيغتين وقارن بعينك. الاختبار العملي يستغرق دقيقة ويحسم القرار أفضل من أي جدول.</p>\n<h2 id=\"testing-method\">كيف تختبر الصيغ بنفسك؟</h2>\n<p>لاختبار الصيغ بنفسك، اضغط صورتك إلى 100 كيلوبايت بكل صيغة وقارن النتائج جنبًا إلى جنب. ركّز على الوجه والنص والحواف.</p>\n<p>استخدم <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> للاختبار السريع. النتيجة تظهر فورًا، ويمكنك التبديل بين الصيغ ومقارنة الجودة بعينك.</p>\n<ul>\n<li>اضغط الصورة نفسها بكل صيغة إلى 100 كيلوبايت.</li>\n<li>قارن الوجه والنص والحواف بالتكبير.</li>\n<li>تحقق من قبول بوابتك للصيغة.</li>\n<li>لاحظ أي صيغة تحافظ على التدرجات أفضل.</li>\n<li>اختر الصيغة الفائزة والتزم بها.</li>\n</ul>\n<h2 id=\"colour-depth\">عمق اللون ولماذا يهم عند 100 كيلوبايت</h2>\n<p>عمق اللون يحدد عدد الألوان التي تستطيع الصيغة تمثيلها. عند 100 كيلوبايت، يصبح عمق اللون محدودًا، فتظهر شرائط في التدرجات الناعمة مثل السماء.</p>\n<p>WebP يتعامل مع التدرجات أفضل من JPG عند الأحجام الصغيرة، لذلك تظهر شرائط أقل. إذا لاحظت شرائط، فجرّب WebP أو ارفع الحجم قليلًا.</p>\n<h2 id=\"sharpness-vs-smoothness\">الحدة مقابل النعومة: كيف تختار أولويتك؟</h2>\n<p>الحدة والنعومة أولويتان متعارضتان. صورة حادة تظهر التفاصيل لكنها قد تُبرز الضجيج، بينما صورة ناعمة تخفي العيوب لكنها تفقد التفاصيل.</p>\n<p>للصور الشخصية، فضّل النعومة قليلًا. وللنصوص والرسوم، فضّل الحدة. اختيار الأولوية الصحيحة يجعل الصورة تبدو أفضل بالحجم نفسه.</p>\n<h2 id=\"format-myths\">خرافات عن الصيغ يجدر تجاهلها</h2>\n<p>من الخرافات الشائعة أن PNG يعني جودة أفضل دائمًا. الحقيقة أن PNG أفضل للرسوم فقط، بينما JPG يتفوق بكثير للصور الفوتوغرافية عند الأحجام الصغيرة.</p>\n<p>وخرافة أخرى أن WebP يفسد الألوان. WebP يحافظ على الألوان مثل JPG، والفرق بينهما لا يُرى إلا عند التكبير الشديد.</p>\n<h2 id=\"archiving-100kb\">كيف تؤرشف الصور عند 100 كيلوبايت؟</h2>\n<p>للأرشفة، لا تعتمد على نسخ 100 كيلوبايت. احتفظ دائمًا بالملف الأصلي بأعلى جودة، واستخدم نسخ 100 كيلوبايت للاستخدام اليومي فقط.</p>\n<p>سمِّ نسخ الأرشيف بوضوح، مثل sora-asliya.jpg للنسخة الأصلية وsora-100kb.jpg للنسخة المضغوطة. التنظيم يمنع الخلط بينهما.</p>\n<h2 id=\"quick-reference\">مرجع سريع: اختيار الصيغة عند 100 كيلوبايت</h2>\n<p>مرجع سريع: صورة فوتوغرافية فـJPG أو WebP، ونص أو رسم فـPNG، وشفافية فـWebP، ولقطة شاشة فقصّ ثم JPG.</p>\n<p>اطبع هذه القاعدة أو احفظها. ستختصر عليك دقائق من التردد في كل مرة تحتاج فيها إلى ضغط صورة.</p>\n<h2 id=\"lossy-vs-lossless\">مع الفقدان مقابل دون فقدان: الفكرة الأساسية وراء المقارنة</h2>\n<p>الضغط مع الفقدان يحذف بيانات لتقليص الحجم، بينما الضغط دون فقدان يحفظ كل شيء. JPG وWebP مع الفقدان، وPNG دون فقدان.</p>\n<p>عند 100 كيلوبايت، الضغط مع الفقدان هو الخيار العملي للصور. الضغط دون فقدان يكلّف مساحة أكبر بكثير مقابل فائدة لا تُرى بالعين.</p>\n<h2 id=\"browser-support\">توافق المتصفحات والأجهزة لكل صيغة</h2>\n<p>معظم المتصفحات الحديثة تدعم الصيغ الثلاث. WebP يعمل في كروم وفايرفوكس وسفاري الحديث، لكن بعض البرامج القديمة ما زالت ترفضه.</p>\n<p>قبل اختيار WebP، تحقق من قبول بوابتك وأنظمتك له. إذا كان هناك شك، فـJPG هو الخيار الآمن الذي يعمل في كل مكان.</p>\n<h2 id=\"future-formats\">ما الذي يأتي بعد WebP؟</h2>\n<p>بعد WebP يأتي AVIF، وهو أصغر حجمًا بجودة مماثلة. لكن دعمه ما زال محدودًا في البوابات وبرامج التحرير.</p>\n<p>في الوقت الحالي، التزم بـJPG وWebP. وعندما ينتشر AVIF أكثر، ستكون الأدوات جاهزة لدعمه تلقائيًا.</p>\n<h2 id=\"how-quality-is-picked\">كيف يختار الضاغط الجودة لكل صيغة؟</h2>\n<p>يختار الضاغط الجودة لكل صيغة بطريقة مختلفة. لـJPG يبحث عن أعلى جودة تناسب الحد، ولـWebP يستخدم خوارزمية مشابهة لكن بكفاءة أعلى.</p>\n<p>لذلك لا تقارن أرقام الجودة بين الصيغ مباشرة. جودة 80 في JPG ليست مثل جودة 80 في WebP. قارن النتيجة النهائية بعينك. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-daght-as-sura-ila-100kb/\">الدليل الكامل لضغط الصورة إلى 100 كيلوبايت</a> و<a href=\"/ar/blog/kayfiyya-taqlil-as-sura-ila-100kb/\">كيفية تقليل صورة إلى 100 كيلوبايت</a>، أو جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> لتغيير الصيغة.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل WebP أفضل دائمًا من JPG عند 100 كيلوبايت؟","answer":"غالبًا نعم للصور الفوتوغرافية، لكن ليس دائمًا. WebP يتفوق بهامش صغير في الحدة والحجم، لكن بعض البوابات القديمة ترفضه. إذا قبلت بوابتك WebP، فهو خيار ممتاز."},{"question":"لماذا تبدو صورتي أسوأ بصيغة PNG عند 100 كيلوبايت؟","answer":"لأن PNG يحفظ الصور دون فقدان، فيضطر إلى التضحية بالأبعاد أو قبول ملف أكبر للوصول إلى 100 كيلوبايت. الصورة الفوتوغرافية بصيغة PNG تبدو أسوأ لأنها فقدت تفاصيل كثيرة أثناء تقليص الأبعاد."},{"question":"هل يمكنني تحويل صورة PNG إلى JPG للوصول إلى 100 كيلوبايت؟","answer":"نعم، وهذه من أفضل الحيل للوصول إلى 100 كيلوبايت. حوّل الصورة الفوتوغرافية من PNG إلى JPG، وستنخفض إلى 100 كيلوبايت بجودة أفضل بكثير في معظم الحالات."},{"question":"هل يحافظ WebP على الألوان نفسها مثل JPG؟","answer":"نعم، في الغالب. WebP يحافظ على الألوان نفسها تقريبًا، وقد يظهر فرق طفيف في التدرجات الناعمة جدًا، لكن معظم العيون لا تلاحظه."},{"question":"ما الصيغة التي أستخدمها لمستند ممسوح عند 100 كيلوبايت؟","answer":"JPG هو الخيار الآمن للمستندات الممسوحة عند 100 كيلوبايت، لأنه يوازن بين وضوح النص وحجم الملف. استخدم PNG فقط إذا كان النص صغيرًا جدًا ويحتاج حدة كاملة."},{"question":"هل يقلل تحويل الصيغ جودة صورتي؟","answer":"تحويل الصيغة نفسه لا يقلل الجودة كثيرًا إذا بدأت من الملف الأصلي. الخسارة تأتي من الضغط القوي، لا من التحويل. لذلك حوّل دائمًا من الأصل لا من نسخة مضغوطة."}];
